@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Rye&display=swap');
:root{--ink:#172538;--muted:#7d8996;--cream:#f7f4ed;--paper:#fffdf9;--gold:#edb448;--red:#e95c48;--navy:#172a40;--blue:#6ca9d9;--green:#57a785;--shadow:0 12px 32px #1f2c3b14}*{box-sizing:border-box}body{margin:0;background:#f1eee8;color:var(--ink);font-family:'DM Sans',sans-serif;font-size:14px;min-height:100vh}.game-shell{max-width:1220px;margin:auto;padding:0 30px}.topbar{height:74px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #dcd9d1}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink)}.brand-mark{background:var(--navy);color:#f4c55f;width:37px;height:37px;border-radius:12px;display:grid;place-items:center;font-size:21px;box-shadow:inset 0 0 0 1px #ffffff20}.brand-copy{display:grid;line-height:1}.brand-copy strong{font-size:14px;letter-spacing:1.55px;font-weight:800}.brand-copy small{margin-top:5px;font-size:9px;color:#89909a;letter-spacing:2px;text-transform:uppercase}.top-actions{display:flex;align-items:center;gap:11px}.resource{height:34px;background:#e8e5de;border:1px solid #dedbd4;border-radius:20px;display:flex;align-items:center;gap:8px;padding:0 7px 0 6px;font-size:12px;font-weight:800;min-width:94px}.resource-icon{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-size:11px;color:#fff}.berry{background:#d9a83b}.gem{background:#6c83cd}.plus{border:0;border-radius:50%;background:#fff;color:#8f969f;width:19px;height:19px;font-size:15px;line-height:16px;cursor:pointer}.icon-button{width:33px;height:33px;border:1px solid #dedbd4;background:#f7f5ef;color:#536273;border-radius:50%;font-weight:700;font-size:15px;cursor:pointer}.mission-strip{display:flex;align-items:center;justify-content:space-between;height:91px}.mission-title{display:flex;align-items:center;gap:13px}.mission-emblem{width:43px;height:43px;border-radius:13px;background:#f8e9c9;color:#ae7d27;display:grid;place-items:center;font-size:21px}.eyebrow{font-size:9px;font-weight:800;letter-spacing:1.65px;color:#a38b5f}.mission-title h1{font-size:18px;margin:3px 0 0;letter-spacing:-.3px}.mission-progress{width:220px}.progress-copy{display:flex;justify-content:space-between;font-size:9px;font-weight:800;letter-spacing:.7px;color:#657386}.progress-copy span:last-child{font-weight:600;letter-spacing:0;color:#9da3a8}.stage-track{display:flex;gap:4px;margin-top:8px}.stage-track i{height:4px;flex:1;background:#ddd9d0;border-radius:3px}.stage-track i.active{background:#e8b44d}.stamina{display:flex;align-items:center;gap:8px;border-left:1px solid #ddd9d0;padding-left:17px}.stamina-icon{font-size:18px;color:#e3a72d}.stamina b,.stamina small{display:block}.stamina b{font-size:11px}.stamina small{font-size:9px;color:#9098a0;margin-top:3px}.stamina-timer{font-size:9px;color:#969da4;border-left:1px solid #dedbd5;padding-left:9px;margin-left:4px}.battlefield{height:402px;border-radius:17px;overflow:hidden;position:relative;background:linear-gradient(180deg,#8ca9b9 0%,#bfd0ce 39%,#e0c599 68%,#986d55 100%);box-shadow:var(--shadow);isolation:isolate}.battle-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,#20395032,transparent 30%,transparent 75%,#20395023),linear-gradient(0deg,#292a3230,transparent 22%);z-index:1}.battle-hud{position:absolute;top:17px;left:20px;right:20px;z-index:5;display:flex;justify-content:space-between;align-items:flex-start}.turn-pill{height:27px;border:1px solid #ffffff79;border-radius:16px;padding:0 11px;display:flex;align-items:center;gap:7px;background:#182c3f72;color:#fff;font-size:9px;letter-spacing:1px;font-weight:800;backdrop-filter:blur(5px)}.turn-pill b{color:#f3c459;border-left:1px solid #ffffff42;padding-left:7px}.turn-dot{width:6px;height:6px;border-radius:50%;background:#74dfab;box-shadow:0 0 8px #74dfab}.chain-display{width:65px;height:65px;border-radius:50%;background:#192d3c90;border:1px solid #f4d2849c;color:white;text-align:center;padding-top:8px;display:flex;flex-direction:column;align-items:center;backdrop-filter:blur(4px);box-shadow:0 0 0 4px #ffffff16}.chain-display span,.chain-display small{font-size:7px;letter-spacing:1.4px;font-weight:800;color:#f8d77f}.chain-display strong{font:20px 'Rye',serif;line-height:20px}.chain-display small{font-size:6px;color:#d9e3e1}.weather{position:absolute;z-index:5;top:84px;right:20px;font-size:7px;letter-spacing:1px;font-weight:800;color:#36505c;background:#ffffff68;border-radius:10px;padding:5px 8px}.weather span{font-size:11px;color:#e0ae48}.weather i{display:inline-block;width:3px;height:3px;border-radius:50%;background:#a18b64;vertical-align:middle;margin:0 5px}.scene{position:absolute;inset:0;overflow:hidden}.sun-glow{position:absolute;right:19%;top:61px;width:117px;height:117px;border-radius:50%;background:#ffe9aa9e;box-shadow:0 0 60px 25px #ffe7a05c}.far-island{position:absolute;bottom:147px;right:15%;width:210px;height:67px;background:#607a6c;border-radius:60% 48% 0 0;opacity:.72;clip-path:polygon(0 100%,8% 62%,20% 47%,30% 54%,40% 24%,52% 43%,61% 9%,75% 47%,90% 31%,100% 100%)}.far-island i{position:absolute;width:3px;height:27px;top:12px;left:35%;background:#52695d;transform:rotate(-30deg)}.far-island i:nth-child(2){left:63%;top:6px;height:34px}.far-island i:nth-child(3){left:78%;top:20px;height:23px}.sea-line{position:absolute;left:0;right:0;height:100px;bottom:68px;background:linear-gradient(180deg,#71a2a3a8,#447b87c9);clip-path:polygon(0 29%,7% 26%,14% 34%,22% 28%,31% 35%,41% 25%,49% 35%,59% 28%,68% 34%,77% 24%,86% 32%,94% 28%,100% 32%,100% 100%,0 100%)}.sea-two{bottom:42px;height:85px;opacity:.69;background:linear-gradient(#598990,#365e6b);clip-path:polygon(0 36%,9% 29%,18% 36%,29% 27%,40% 33%,52% 24%,61% 33%,72% 25%,84% 34%,95% 27%,100% 30%,100% 100%,0 100%)}.wave{position:absolute;z-index:1;bottom:65px;height:6px;width:130px;border-radius:50%;border-top:2px solid #e6e8d1a8;transform:rotate(-4deg)}.wave-one{left:10%}.wave-two{left:39%;bottom:49px;width:88px}.enemy-ship{position:absolute;z-index:2;right:22%;bottom:129px;width:142px;height:151px;transform:scale(.82);transform-origin:bottom center;filter:drop-shadow(0 7px 2px #23384926)}.enemy-flag{position:absolute;top:0;left:87px;width:22px;height:17px;background:#23313b;color:#f5e1b5;font-size:10px;text-align:center;clip-path:polygon(0 0,100% 0,82% 50%,100% 100%,0 100%)}.mast{position:absolute;top:13px;left:97px;height:99px;width:3px;background:#604f3a}.sail{position:absolute;border:2px solid #725f43;background:#e7d8b8}.sail-back{top:26px;left:35px;width:55px;height:69px;clip-path:polygon(0 0,100% 10%,87% 100%,20% 82%);background:#d2c19e}.sail-front{top:33px;left:98px;width:40px;height:61px;clip-path:polygon(0 0,100% 12%,88% 100%,0 85%);display:grid;place-items:center;color:#78573f;font-size:18px}.ship-hull{position:absolute;bottom:12px;left:3px;width:135px;height:35px;background:linear-gradient(#553e34 0 22%,#392d2b 23%);clip-path:polygon(0 0,100% 0,83% 70%,64% 100%,21% 94%,8% 62%)}.hull-line{position:absolute;bottom:25px;left:9px;width:119px;border-top:2px solid #bb8b51}.enemy-area{position:absolute;z-index:4;right:9.5%;top:133px;width:193px}.enemy-nameplate{display:flex;align-items:center;gap:6px;color:#fff;text-shadow:0 1px 5px #27384599}.enemy-type{font-size:7px;background:#b8493d;padding:4px 5px;border-radius:4px;letter-spacing:.8px;font-weight:800}.enemy-nameplate strong{font-size:13px;white-space:nowrap}.enemy-level{font-size:8px;color:#f5e4bd;margin-left:auto}.enemy-hp-wrap{margin-top:8px;position:relative}.enemy-hp{height:7px;border-radius:5px;background:#24313b83;border:1px solid #ffffff80;overflow:hidden}.enemy-hp i{display:block;width:100%;height:100%;background:linear-gradient(90deg,#f0765b,#df4b40);border-radius:5px;transition:width .5s}.enemy-hp-wrap span{display:block;text-align:right;font-size:8px;color:white;text-shadow:0 1px 3px #253441;margin-top:4px}.enemy-status{display:inline-flex;align-items:center;gap:4px;margin-top:7px;border-radius:10px;background:#20384c75;padding:4px 7px;color:#eff4ed;font-size:8px;backdrop-filter:blur(3px)}.enemy-status span{color:#f2c565}.enemy-status b{display:grid;place-items:center;width:15px;height:15px;border-radius:50%;background:#dc5d4c;color:white;font-size:8px;margin-left:3px}.foreground-ship{position:absolute;z-index:3;left:11%;bottom:-4px;width:310px;height:142px}.player-mast{position:absolute;z-index:1;left:137px;top:1px;width:4px;height:114px;background:#614b36;box-shadow:1px 0 #e1bd7c}.player-sail{position:absolute;z-index:2;left:56px;top:13px;width:90px;height:90px;clip-path:polygon(0 0,100% 9%,87% 100%,11% 83%);background:linear-gradient(135deg,#fff8df,#d9c9a7);border:2px solid #806c4b;display:grid;place-items:center;color:#775743;font-size:26px}.player-sail:after{content:'';position:absolute;right:0;top:0;height:100%;width:2px;background:#806c4b}.player-hull{position:absolute;bottom:0;left:0;width:310px;height:64px;background:linear-gradient(180deg,#925f3c,#72482f 60%,#4d3e35);clip-path:polygon(0 0,100% 0,88% 58%,76% 87%,58% 100%,17% 88%,6% 54%);border-top:5px solid #e6c187}.ship-glint{position:absolute;bottom:44px;left:25px;width:257px;border-top:2px solid #e5c28a;opacity:.8}.battle-bottom{position:absolute;z-index:5;bottom:0;left:0;right:0;height:58px;padding:9px 22px;background:linear-gradient(0deg,#15283bd6,#233c504f);color:#fff}.crew-summary{display:flex;align-items:center;gap:7px;font-size:8px;letter-spacing:.65px}.crew-summary b{font-size:8px;letter-spacing:1px}.crew-summary #crewHpLabel{margin-left:auto;font-size:8px;color:#e3e8e6;letter-spacing:0}.crew-dot{width:6px;height:6px;background:#68dca1;border-radius:50%;box-shadow:0 0 7px #68dca1}.crew-hp{height:4px;background:#ffffff4c;border-radius:4px;margin-top:7px;overflow:hidden}.crew-hp i{display:block;width:100%;height:100%;background:#75d39c;border-radius:4px;transition:width .5s}.battle-hint{position:absolute;bottom:15px;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:9px;color:#fff;text-shadow:0 1px 3px #15283b}.hint-spark{color:#ffdc7f;margin-right:5px}.battle-controls{position:absolute;right:19px;bottom:68px;z-index:6;display:flex;gap:6px}.auto-button,.speed-button{border:1px solid #ffffff91;background:#172b3a87;color:#fff;border-radius:6px;height:27px;font-size:8px;font-weight:800;letter-spacing:.7px;cursor:pointer;backdrop-filter:blur(5px)}.auto-button{padding:0 9px}.auto-button span{color:#f0c458;margin-right:4px}.auto-button i{display:inline-block;width:16px;height:9px;border-radius:6px;background:#88939a;margin-left:4px;vertical-align:middle;position:relative}.auto-button i:after{content:'';position:absolute;width:6px;height:6px;left:2px;top:1.5px;border-radius:50%;background:white;transition:.2s}.auto-button.on i{background:#63b585}.auto-button.on i:after{left:8px}.speed-button{padding:0 9px}.battle-toast{position:absolute;z-index:8;top:34%;left:50%;transform:translate(-50%,-50%) scale(.8);opacity:0;pointer-events:none;color:#fff;text-align:center;font:26px 'Rye',serif;text-shadow:0 3px 12px #25364b,0 1px 2px #15283b;transition:.22s}.battle-toast.show{opacity:1;transform:translate(-50%,-50%) scale(1)}.crew-section{padding:19px 0 12px}.crew-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:12px}.crew-heading h2{font-size:15px;margin:4px 0 0;letter-spacing:-.2px}.crew-heading h2 span{font-size:9px;color:#9ba0a2;margin-left:4px;letter-spacing:.5px}.crew-instructions{display:flex;align-items:center;gap:7px;color:#858d95;font-size:9px}.crew-instructions kbd{font-family:inherit;font-weight:800;font-size:7px;letter-spacing:.6px;padding:4px 6px;background:#e5e2db;border-radius:4px;color:#69717c}.crew-cards{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.crew-card{position:relative;min-width:0;height:145px;border:1px solid #e1ded7;border-radius:11px;background:#fffefa;padding:9px 9px 8px;cursor:pointer;transition:transform .18s,box-shadow .18s,border-color .18s;overflow:hidden;text-align:left;color:var(--ink);box-shadow:0 4px 11px #1f2c3b08}.crew-card:hover{transform:translateY(-3px);box-shadow:0 9px 20px #1f2c3b17}.crew-card.selected{border-color:#e4b54e;box-shadow:0 0 0 2px #e4b54e38,0 8px 18px #293a4c17}.crew-card.done{opacity:.55;filter:saturate(.65);transform:scale(.97)}.crew-card:disabled{cursor:default}.card-top{display:flex;align-items:center;justify-content:space-between;height:16px}.type-badge{font-size:7px;font-weight:800;letter-spacing:.7px;color:#e75f52}.type-badge.green{color:#489773}.type-badge.blue{color:#568fc2}.type-badge.yellow{color:#c3922c}.card-cost{font-size:7px;color:#939ba1;font-weight:700}.portrait{position:relative;height:70px;margin:3px 0 4px;border-radius:7px;overflow:hidden;display:grid;place-items:center;background:radial-gradient(circle at 50% 32%,#f8cb93,#d77e5e 60%,#833f49)}.portrait:before{content:'';position:absolute;width:51px;height:57px;left:calc(50% - 25px);top:8px;background:#f4c59c;border-radius:48% 48% 43% 43%;box-shadow:0 8px 0 -3px #6a3d32}.portrait:after{content:'';position:absolute;width:64px;height:24px;bottom:-6px;background:#2c4452;border-radius:55% 55% 0 0}.portrait .hair{position:absolute;z-index:1;left:calc(50% - 27px);top:5px;width:54px;height:26px;border-radius:60% 60% 38% 30%;background:#442b24;clip-path:polygon(5% 0,95% 0,100% 54%,81% 75%,70% 41%,55% 68%,45% 37%,26% 74%,15% 47%,0 66%)}.portrait .face-mark{position:absolute;z-index:2;top:37px;left:calc(50% - 8px);width:5px;height:2px;border-radius:50%;background:#4b3331;box-shadow:12px 0 #4b3331}.portrait .portrait-icon{position:absolute;z-index:3;bottom:6px;right:5px;font-size:17px;filter:drop-shadow(0 1px 1px #443)}.portrait.luffy{background:radial-gradient(circle at 50% 35%,#ffd1a0,#bd6050 65%,#873b47)}.portrait.luffy .hair{background:#4c3021}.portrait.luffy:after{background:#bb4036}.portrait.zoro{background:radial-gradient(circle at 50% 35%,#d1d79b,#719064 65%,#415c53)}.portrait.zoro .hair{background:#7d9961;clip-path:polygon(0 22%,27% 0,36% 26%,56% 0,61% 25%,87% 4%,100% 39%,79% 71%,21% 69%)}.portrait.zoro:after{background:#455547}.portrait.nami{background:radial-gradient(circle at 50% 35%,#ffd1a0,#d78f6c 62%,#7d5172)}.portrait.nami .hair{background:#e89a43;clip-path:polygon(0 0,100% 0,92% 84%,75% 60%,66% 100%,51% 56%,33% 94%,25% 51%,7% 79%)}.portrait.nami:after{background:#e6a14a}.portrait.sanji{background:radial-gradient(circle at 50% 35%,#f4cb9b,#9b9f82 62%,#495967)}.portrait.sanji .hair{background:#e2bf66;clip-path:polygon(0 0,100% 0,95% 45%,75% 34%,69% 71%,54% 57%,48% 37%,32% 40%,20% 74%,0 59%)}.portrait.sanji:after{background:#354a5a}.portrait.chopper{background:radial-gradient(circle at 50% 35%,#f7d8bb,#9c8b87 65%,#4d6883)}.portrait.chopper:before{width:45px;height:40px;top:19px;background:#ad765a;border-radius:50%}.portrait.chopper .hair{width:56px;height:32px;top:10px;background:#8b4d38;border-radius:50%;clip-path:polygon(0 0,100% 0,100% 80%,76% 63%,66% 100%,43% 64%,19% 91%,13% 48%)}.portrait.chopper:after{background:#5e81a0}.portrait.robin{background:radial-gradient(circle at 50% 35%,#ebc4a4,#705f82 66%,#394858)}.portrait.robin .hair{background:#463747;clip-path:polygon(0 0,100% 0,95% 100%,79% 61%,66% 80%,52% 54%,38% 79%,23% 59%,5% 100%)}.portrait.robin:after{background:#655878}.card-name{display:block;font-size:11px;font-weight:800;line-height:1.1}.card-role{display:block;color:#9aa0a3;font-size:8px;margin-top:3px}.power{position:absolute;right:8px;bottom:9px;color:#d29b37;font-weight:800;font-size:8px}.card-order{position:absolute;right:7px;top:8px;z-index:4;background:#e7b54b;color:white;width:16px;height:16px;border-radius:50%;display:grid;place-items:center;font-size:8px;font-weight:800;opacity:0;transform:scale(.5);transition:.2s}.crew-card.selected .card-order,.crew-card.done .card-order{opacity:1;transform:scale(1)}.crew-card.done .card-order{background:#67a989}.crew-card.selected .tap-ring{animation:ring 1.15s ease-in-out infinite}.tap-ring{position:absolute;z-index:3;inset:0;border:2px solid transparent;border-radius:10px;pointer-events:none}.crew-card.selected .tap-ring{border-color:#f1ca63}@keyframes ring{50%{box-shadow:0 0 0 5px #efc6551f}}.crew-footer{display:flex;align-items:center;justify-content:space-between;height:32px;margin-top:7px}.type-legend{display:flex;align-items:center;gap:5px;font-size:7px;font-weight:800;letter-spacing:.5px;color:#9a9fa1}.legend-dot{width:6px;height:6px;border-radius:50%;margin-left:7px}.legend-dot:first-child{margin-left:0}.legend-dot.red{background:#e56555}.legend-dot.green{background:#5ba981}.legend-dot.blue{background:#6a9dc8}.legend-dot.yellow{background:#d4a23c}.reset-button{background:none;border:0;color:#9b9b93;font-size:12px;cursor:pointer}.reset-button span{font-size:8px;letter-spacing:.6px;font-weight:800}footer{height:35px;border-top:1px solid #dedbd4;display:flex;justify-content:space-between;align-items:center;color:#a5a39b;font-size:7px;letter-spacing:1px;font-weight:700}footer i{font-style:normal;color:#d2ae66;margin:0 3px}footer b{color:#de735b}.modal-backdrop{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:20px;background:#142335a8;backdrop-filter:blur(5px)}.modal-backdrop[hidden]{display:none}.modal{width:min(390px,100%);background:#fffdf8;border-radius:17px;padding:32px;text-align:center;position:relative;box-shadow:0 22px 65px #101c2c50}.modal-close{position:absolute;right:14px;top:12px;background:none;border:0;font-size:25px;color:#90989d;cursor:pointer}.modal-icon{margin:0 auto 13px;width:48px;height:48px;border-radius:15px;background:#f7e9c8;color:#bd8a2c;display:grid;place-items:center;font-size:21px}.modal h2{font-size:23px;margin:5px 0 10px}.modal p{font-size:13px;line-height:1.65;color:#7a838b;margin:0 0 22px}.modal-actions{display:flex;justify-content:center;gap:9px;flex-wrap:wrap}.primary-button,.secondary-button{border:0;border-radius:7px;padding:12px 18px;font-size:9px;letter-spacing:.8px;font-weight:800;cursor:pointer}.primary-button{background:#1d3448;color:#fff}.secondary-button{background:#f2e7d2;color:#8a63